            "object",
            "any",
            "void"
          ],
          "default": "boolean"
        }
      },
      "required": ["call"]
    },
    "LogicExpression": {
      "type": "object",
      "description": "A boolean expression used for conditional state (e.g. 'enabled').",
      "oneOf": [
        {
          "properties": {
