          },
          "required": ["or"]
        },
        {
          "properties": {
            "not": {
              "$ref": "#/$defs/LogicExpression"
            }
          },
          "required": ["not"]
        },
        {
          "allOf": [
            {
              "$ref": "#/$defs/FunctionCall"
            },
            {
              "properties": {
