                  "const": "boolean"
                }
              }
            }
          ]
        },
        {
          "properties": {
            "true": {
              "const": true
            }
          },
          "required": ["true"]
        },
        {
          "properties": {
            "false": {
              "const": false
            }
          },
          "required": ["false"]
        }
      ]
    },
    "CheckRule": {
      "type": "object",
      "description": "A single validation rule applied to an input component.",
